/**
 * Vertice - Herramienta: Retícula modular
 * ------------------------------------------------------------------
 * Dibuja una retícula de columnas y filas sobre la mesa de trabajo
 * activa, al estilo de los sistemas reticulares suizos.
 *
 * No necesita seleccion: trabaja siempre sobre la mesa activa.
 */

if (typeof CG === "undefined") { var CG = {}; }

(function (CG) {

    var NOMBRE_CAPA = "RETICULA";

    CG.reticula = function (opcionesJSON) {
        try {
            var opt = eval("(" + opcionesJSON + ")");
            CG.idioma = (opt && opt._idioma) || "es";

            var ctx = CG.contextoMesa();
            if (ctx.error) return '{"ok":false,"error":"' + CG.escapaJSON(ctx.error) + '"}';

            var doc = ctx.doc;
            var mesa = ctx.mesa;
            var L = mesa[0], T = mesa[1], R = mesa[2], B = mesa[3];

            var cols = Math.max(1, Math.round(opt.columnas));
            var filas = Math.max(1, Math.round(opt.filas));
            var u = opt.unidad;

            // Margenes y medianiles: en mm o en % del lado correspondiente.
            var mIzq = CG.aPuntos(opt.margenIzquierdo, u, ctx.ancho);
            var mDer = CG.aPuntos(opt.margenDerecho,   u, ctx.ancho);
            var mSup = CG.aPuntos(opt.margenSuperior,  u, ctx.alto);
            var mInf = CG.aPuntos(opt.margenInferior,  u, ctx.alto);
            var gutH = CG.aPuntos(opt.medianilH, u, ctx.ancho);
            var gutV = CG.aPuntos(opt.medianilV, u, ctx.alto);

            var anchoUtil = ctx.ancho - mIzq - mDer;
            var altoUtil  = ctx.alto  - mSup - mInf;

            if (anchoUtil <= 0 || altoUtil <= 0) {
                return '{"ok":false,"error":"Los márgenes no dejan espacio útil en la mesa."}';
            }

            var anchoCol = (anchoUtil - gutH * (cols - 1)) / cols;
            var altoFila = (altoUtil - gutV * (filas - 1)) / filas;

            if (anchoCol <= 0) {
                return '{"ok":false,"error":"Demasiadas columnas o medianil excesivo para este ancho."}';
            }
            if (altoFila <= 0) {
                return '{"ok":false,"error":"Demasiadas filas o medianil excesivo para esta altura."}';
            }

            // --- Capa y grupo ---
            var capa;
            try {
                capa = doc.layers.getByName(CG.N(NOMBRE_CAPA));
                capa.locked = false;
                capa.visible = true;
            } catch (e) {
                capa = doc.layers.add();
                capa.name = CG.N(NOMBRE_CAPA);
            }
            try { capa.zOrder(ZOrderMethod.BRINGTOFRONT); } catch (e) {}

            // Una retícula por mesa de trabajo: se reemplaza la de esta mesa.
            var nombreGrupo = "Retícula mesa " + (ctx.indice + 1);
            for (var g = capa.groupItems.length - 1; g >= 0; g--) {
                if (capa.groupItems[g].name === nombreGrupo) capa.groupItems[g].remove();
            }
            var raiz = capa.groupItems.add();
            raiz.name = nombreGrupo;

            var rgb = CG.hexARgb(opt.color) || [0, 174, 239];
            var est = {
                color: CG.creaColor(doc, rgb[0], rgb[1], rgb[2]),
                grosor: opt.grosor,
                punteado: opt.punteado,
                opacidad: opt.opacidad
            };

            var nLineas = 0;
            var i;

            // --- Columnas: se traza el borde izquierdo y el derecho de cada una,
            //     que es lo que produce el par de lineas del medianil. ---
            if (opt.columnasVisibles) {
                var gc = raiz.groupItems.add();
                gc.name = CG.N("Columnas");
                for (i = 0; i < cols; i++) {
                    var x1 = L + mIzq + i * (anchoCol + gutH);
                    var x2 = x1 + anchoCol;
                    CG.dibujaLinea(gc, [x1, T], [x1, B], est);
                    CG.dibujaLinea(gc, [x2, T], [x2, B], est);
                    nLineas += 2;
                }
            }

            // --- Filas ---
            if (opt.filasVisibles) {
                var gf = raiz.groupItems.add();
                gf.name = CG.N("Filas");
                for (i = 0; i < filas; i++) {
                    var y1 = T - mSup - i * (altoFila + gutV);
                    var y2 = y1 - altoFila;
                    CG.dibujaLinea(gf, [L, y1], [R, y1], est);
                    CG.dibujaLinea(gf, [L, y2], [R, y2], est);
                    nLineas += 2;
                }
            }

            // --- Caja de márgenes ---
            if (opt.margenes) {
                var gm = raiz.groupItems.add();
                gm.name = CG.N("Margenes");
                var ml = L + mIzq, mr = R - mDer, mt = T - mSup, mb = B + mInf;
                CG.dibujaLinea(gm, [ml, mt], [mr, mt], est);
                CG.dibujaLinea(gm, [mr, mt], [mr, mb], est);
                CG.dibujaLinea(gm, [mr, mb], [ml, mb], est);
                CG.dibujaLinea(gm, [ml, mb], [ml, mt], est);
                nLineas += 4;
            }

            // --- Línea base tipográfica ---
            var nBase = 0;
            if (opt.lineaBase && opt.interlinea > 0) {
                var gb = raiz.groupItems.add();
                gb.name = CG.N("Linea base");
                var paso = CG.aPuntos(opt.interlinea, u === "mm" ? "mm" : "mm", ctx.alto);
                // La linea base siempre se expresa en mm: es una medida tipografica.
                if (paso > 0.5) {
                    for (var y = T - mSup; y > B + mInf - 0.001; y -= paso) {
                        CG.dibujaLinea(gb, [L, y], [R, y], est);
                        nBase++;
                        if (nBase > 2000) break;        // salvaguarda
                    }
                }
            }

            if (raiz.pageItems.length === 0) {
                raiz.remove();
                if (capa.pageItems.length === 0) capa.remove();
                return '{"ok":false,"error":"No se seleccionó ningún elemento de la retícula."}';
            }

            var guias = 0;
            if (opt.convertirGuias) guias = CG.convierteEnGuias(raiz);

            if (opt.bloquear) capa.locked = true;
            app.redraw();

            return '{"ok":true,' +
                   '"lineas":' + nLineas + ',' +
                   '"base":' + nBase + ',' +
                   '"guias":' + guias + ',' +
                   '"columnas":' + cols + ',' +
                   '"filas":' + filas + ',' +
                   '"anchoColumna":' + (anchoCol).toFixed(2) + ',' +
                   '"altoFila":' + (altoFila).toFixed(2) + '}';

        } catch (e) {
            return '{"ok":false,"error":"' +
                   CG.escapaJSON("Error interno: " + e + " (línea " + e.line + ")") + '"}';
        }
    };

})(CG);
